export class OnlyText {
 text(): string { return `SymbolGlyph('arrow').rotate({ angle: this.expanded ? 0 : 180 }); this.expanded = !this.expanded;`; }
}

  @Builder
  renderDetails() {
    Row() {
      SymbolGlyph('arrow').rotate({ angle: this.expanded ? 0 : 180 });
    }.onClick(() => {
      this.expanded = !this.expanded;
    });
  }
  build() { this.renderDetails(); }
}

  @Builder
  renderDetails() {
    Row() {
      SymbolGlyph('arrow').rotate({ angle: this.displayed ? 0 : 180 });
    }.onClick(() => {
      this.selected = !this.selected;
    });
  }
  build() { this.renderDetails(); }
}

export class Quoted {
 text(): string { return "SymbolGlyph('arrow').rotate({ angle: this.expanded ? 0 : 180 }); this.expanded = !this.expanded;"; }
}
